mapper.sql:
FROM byai_session s
JOIN byai_session_member u ON u.session_id = s.session_id
WHERE s.enterprise_id = #{enterpriseId}
  AND s.session_type = 'hs_as'
  AND s.session_id != #{sourceId}
  AND u.mem_obj_type = 'USER' AND u.mem_obj_id = #{userId}
  AND (s.state IS NULL OR s.state NOT IN ('GROUP_DISSOLVED', 'CLOSED', 'GROUP_CHAT_ROUTING', 'GROUP_CHAT_DISPATCH'))

  AND LOWER(s.session_name) LIKE #{keyword} ESCAPE '\'
